def detect_intrusion(packet_log: list[dict]) -> list[dict]:
    suspicious = []
    ip_counts = {}

    for packet in packet_log:
        src_ip = packet.get("src_ip")
        dst_port = packet.get("dst_port")
        payload_size = packet.get("payload_size", 0)

        if src_ip:
            ip_counts[src_ip] = ip_counts.get(src_ip, 0) + 1

        if dst_port in {22, 23, 3389, 445} and payload_size > 1000:
            suspicious.append(packet)
        elif packet.get("flags", {}).get("syn") and not packet.get("flags", {}).get("ack"):
            if ip_counts.get(src_ip, 0) > 50:
                suspicious.append(packet)

    return suspicious
```

