import pyshark
from collections import Counter
import math

def analyze_dns_traffic(pcap_file: str) -> dict:
    suspicious = {'dga': [], 'tunneling': [], 'exfiltration': []}
    domain_stats = Counter()

    capture = pyshark.FileCapture(pcap_file, display_filter='dns.flags.response == 0')

    for packet in capture:
        try:
            domain = packet.dns.qry_name.lower()
            domain_stats[domain] += 1

            # DGA: Hög entropi och långt namn
            if len(domain) > 15:
                prob = [float(domain.count(c)) / len(domain) for c in dict.fromkeys(list(domain))]
                entropy = - sum(p * math.log2(p) for p in prob)
                if entropy > 3.5:
                    suspicious['dga'].append(domain)

            # Tunneling: TXT- eller NULL-frågor
            if hasattr(packet.dns, 'qry_type') and packet.dns.qry_type in ('16', '10'):
                suspicious['tunneling'].append(domain)

            # Exfiltration: Onormalt antal förfrågningar för en underdomän
            if domain.count('.') > 3:
                suspicious['exfiltration'].append(domain)

        except AttributeError:
            continue

    capture.close()
    return {k: list(set(v)) for k, v in suspicious.items()}
```

