def harden_ssh_config(config_path: str) -> dict:
    insecure_settings = {
        "PermitRootLogin": "no",
        "PasswordAuthentication": "no",
        "PermitEmptyPasswords": "no",
        "X11Forwarding": "no",
        "Protocol": "2"
    }
    recommendations = {}

    try:
        with open(config_path, 'r') as f:
            content = f.read()

        for setting, secure_value in insecure_settings.items():
            found = False
            for line in content.splitlines():
                line = line.strip()
                if not line or line.startswith("#"):
                    continue
                parts = line.split(None, 1)
                if len(parts) == 2 and parts[0].lower() == setting.lower():
                    found = True
                    if parts[1].strip() != secure_value:
                        recommendations[setting] = secure_value
                    break

            if not found:
                recommendations[setting] = secure_value

    except FileNotFoundError:
        recommendations["Error"] = "File not found"

    return recommendations
